            "content": "    1 | \/**\n    2 |  * Email Auth Hook \u2014 PHP\/MySQL Backend\n    3 |  *\n    4 |  * All authentication is handled server-side via the PHP API.\n    5 |  * localStorage is no longer used as the primary auth store.\n    6 |  * Sessions are managed via Bearer tokens stored in localStorage.\n    7 |  *\/\n    8 | \n    9 | import type React from \"react\";\n   10 | import {\n   11 |   createContext,\n   12 |   useCallback,\n   13 |   useContext,\n   14 |   useEffect,\n   15 |   useRef,\n   16 |   useState,\n   17 | } from \"react\";\n   18 | import type { StaffRole } from \"..\/types\";\n   19 | import { post, get, setAuthToken, clearAuthToken } from \"..\/lib\/api\";\n   20 | \n   21 | export interface DoctorAccount {\n   22 |   id: number;\n   23 |   email: string;\n   24 |   full_name: string;\n   25 |   name_bn: string;\n   26 |   role: StaffRole;\n   27 |   specialization: string;\n   28 |   phone: string;\n   29 |   photo_url?: string;\n   30 |   signature_url?: string;\n   31 |   bmdc_registration?: string;\n   32 | }\n   33 | \n   34 | export interface PatientAccount {\n   35 |   id: number;\n   36 |   patient_id: number;\n   37 |   phone: string;\n   38 |   full_name: string;\n   39 |   name_bn: string;\n   40 |   gender?: string;\n   41 |   date_of_birth?: string;\n   42 |   register_number?: string;\n   43 |   photo_url?: string;\n   44 |   status: \"pending\" | \"approved\" | \"rejected\";\n   45 | }\n   46 | \n   47 | export interface AuditLogEntry {\n   48 |   id: string;\n   49 |   timestamp: string;\n   50 |   userRole: StaffRole | \"admin\" | \"patient\";\n   51 |   userName: string;\n   52 |   action: string;\n   53 |   target: string;\n   54 | }\n   55 | \n   56 | const VALID_ROLES: StaffRole[] = [\n   57 |   \"admin\",\n   58 |   \"consultant_doctor\",\n   59 |   \"assistant_professor\",\n   60 |   \"associate_professor\",\n   61 |   \"professor\",\n   62 |   \"medical_officer\",\n   63 |   \"assistant_registrar\",\n   64 |   \"registrar\",\n   65 |   \"intern_doctor\",\n   66 |   \"nurse\",\n   67 |   \"reception\",\n   68 |   \"staff\",\n   69 |   \"patient\",\n   70 |   \"doctor\",\n   71 | ];\n   72 | \n   73 | export function isConsultantLevel(role: StaffRole): boolean {\n   74 |   return [\n   75 |     \"consultant_doctor\",\n   76 |     \"assistant_professor\",\n   77 |     \"associate_professor\",\n   78 |     \"professor\",\n   79 |   ].includes(role);\n   80 | }\n   81 | \n   82 | \/\/ \u2500\u2500 Legacy localStorage registry helpers (kept for backward compatibility) \u2500\u2500\n   83 | \n   84 | export function loadRegistry(): DoctorAccount[] {\n   85 |   return [];\n   86 | }\n   87 | \n   88 | export function saveRegistry(_registry: DoctorAccount[]): void {\n   89 |   \/\/ No-op \u2014 registry is server-side\n   90 | }\n   91 | \n   92 | export function loadPatientRegistry(): PatientAccount[] {\n   93 |   return [];\n   94 | }\n   95 | \n   96 | export function savePatientRegistry(_registry: PatientAccount[]): void {\n   97 |   \/\/ No-op \u2014 registry is server-side\n   98 | }\n   99 | \n  100 | export function appendAuditLog(_entry: Omit<AuditLogEntry, \"id\">): void {\n  101 |   \/\/ Audit logging handled by PHP backend\n  102 | }\n  103 | \n  104 | export function getAuditLog(): AuditLogEntry[] {\n  105 |   return [];\n  106 | }\n  107 | \n  108 | export function loadSignUpMap(): Record<string, boolean> {\n  109 |   return {};\n  110 | }\n  111 | \n  112 | export function saveSignUpMap(_map: Record<string, boolean>): void {\n  113 |   \/\/ No-op\n  114 | }\n  115 | \n  116 | export function setSignUpEnabled(_registerNumber: string, _enabled: boolean): void {\n  117 |   \/\/ No-op\n  118 | }\n  119 | \n  120 | export function isSignUpEnabled(_registerNumber: string): boolean {\n  121 |   return true;\n  122 | }\n  123 | \n  124 | \/\/ Normalize register number: \"0001\/26\" and \"1\/26\" treated as equal\n  125 | function normalizeRegNo(rn: string): string {\n  126 |   const parts = rn.trim().split(\"\/\");\n  127 |   if (parts.length === 2) {\n  128 |     const num = Number.parseInt(parts[0].trim(), 10);\n  129 |     return `${Number.isNaN(num) ? parts[0].trim() : num}\/${parts[1].trim()}`;\n  130 |   }\n  131 |   return rn.trim().toLowerCase();\n  132 | }\n  133 | \n  134 | interface EmailAuthContextValue {\n  135 |   currentDoctor: DoctorAccount | null;\n  136 |   currentPatient: PatientAccount | null;\n  137 |   isInitializing: boolean;\n  138 |   isLoggingIn: boolean;\n  139 |   authError: string | null;\n  140 |   signUp: (data: {\n  141 |     email: string;\n  142 |     password: string;\n  143 |     full_name: string;\n  144 |     role?: string;\n  145 |     specialization?: string;\n  146 |     phone?: string;\n  147 |   }) => Promise<void>;\n  148 |   signIn: (email: string, password: string) => Promise<void>;\n  149 |   signOut: () => Promise<void>;\n  150 |   updateProfile: (data: Partial<DoctorAccount>) => Promise<void>;\n  151 |   getPendingAccounts: () => Promise<DoctorAccount[]>;\n  152 |   approveAccount: (id: number, role?: string) => Promise<void>;\n  153 |   approveAccountWithRole: (id: number, role: StaffRole) => Promise<void>;\n  154 |   rejectAccount: (id: number) => Promise<void>;\n  155 |   reassignRole: (id: number, role: StaffRole) => Promise<void>;\n  156 |   \/\/ Patient auth\n  157 |   patientSignUp: (data: {\n  158 |     registerNumber: string;\n  159 |     phone: string;\n  160 |     password: string;\n  161 |   }) => Promise<void>;\n  162 |   patientSignIn: (phone: string, password: string) => Promise<void>;\n  163 |   patientSignOut: () => void;\n  164 |   getPendingPatients: () => Promise<PatientAccount[]>;\n  165 |   approvePatient: (id: number) => Promise<void>;\n  166 |   rejectPatient: (id: number) => Promise<void>;\n  167 |   updatePatientCredentials: (\n  168 |     registerNumber: string,\n  169 |     newPhone?: string,\n  170 |     newPassword?: string,\n  171 |   ) => Promise<void>;\n  172 | }\n  173 | \n  174 | const EmailAuthContext = createContext<EmailAuthContextValue | null>(null);\n  175 | \n  176 | export function EmailAuthProvider({ children }: { children: React.ReactNode }) {\n  177 |   const [currentDoctor, setCurrentDoctor] = useState<DoctorAccount | null>(null);\n  178 |   const [currentPatient, setCurrentPatient] = useState<PatientAccount | null>(null);\n  179 |   const [isInitializing, setIsInitializing] = useState(true);\n  180 |   const [isLoggingIn, setIsLoggingIn] = useState(false);\n  181 |   const [authError, setAuthError] = useState<string | null>(null);\n  182 | \n  183 |   \/\/ Restore session on mount by verifying the stored token\n  184 |   useEffect(() => {\n  185 |     const restoreSession = async () => {\n  186 |       try {\n  187 |         const token = localStorage.getItem(\"phpAuthToken\");\n  188 |         if (token) {\n  189 |           \/\/ Try to verify the session\n  190 |           const result = await get<{ user: DoctorAccount }>(\"\/auth\/verify.php\");\n  191 |           if (result?.user) {\n  192 |             setCurrentDoctor(result.user);\n  193 |             localStorage.setItem(\"app_current_user_email\", result.user.email);\n  194 |           }\n  195 |         }\n  196 | \n  197 |         \/\/ Check for patient session\n  198 |         const patientToken = localStorage.getItem(\"phpPatientToken\");\n  199 |         if (patientToken) {\n  200 |           \/\/ Patient session restore would go here\n  201 |           \/\/ For now just clear it and let them re-login\n  202 |         }\n  203 |       } catch {\n  204 |         \/\/ Token invalid or expired \u2014 clear it\n  205 |         localStorage.removeItem(\"phpAuthToken\");\n  206 |         localStorage.removeItem(\"app_current_user_email\");\n  207 |       } finally {\n  208 |         setIsInitializing(false);\n  209 |       }\n  210 |     };\n  211 |     restoreSession();\n  212 |   }, []);\n  213 | \n  214 |   const signUp = useCallback(\n  215 |     async (data: {\n  216 |       email: string;\n  217 |       password: string;\n  218 |       full_name: string;\n  219 |       role?: string;\n  220 |       specialization?: string;\n  221 |       phone?: string;\n  222 |     }) => {\n  223 |       setIsLoggingIn(true);\n  224 |       setAuthError(null);\n  225 |       try {\n  226 |         const result = await post<{ status: string; message: string }>(\"\/auth\/register.php\", {\n  227 |           email: data.email,\n  228 |           password: data.password,\n  229 |           full_name: data.full_name,\n  230 |           role: data.role ?? \"doctor\",\n  231 |           specialization: data.specialization ?? \"\",\n  232 |           phone: data.phone ?? \"\",\n  233 |         });\n  234 |         throw new Error(result.message || \"Account created! Please wait for admin approval before logging in.\");\n  235 |       } catch (e: unknown) {\n  236 |         const msg = e instanceof Error ? e.message : \"Sign up failed.\";\n  237 |         setAuthError(msg);\n  238 |         throw e;\n  239 |       } finally {\n  240 |         setIsLoggingIn(false);\n  241 |       }\n  242 |     },\n  243 |     [],\n  244 |   );\n  245 | \n  246 |   const signIn = useCallback(async (email: string, password: string) => {\n  247 |     setIsLoggingIn(true);\n  248 |     setAuthError(null);\n  249 |     try {\n  250 |       const result = await post<{ token: string; user: DoctorAccount }>(\"\/auth\/login.php\", {\n  251 |         email,\n  252 |         password,\n  253 |       });\n  254 |       setAuthToken(result.token);\n  255 |       localStorage.setItem(\"app_current_user_email\", result.user.email);\n  256 |       setCurrentDoctor(result.user);\n  257 |     } catch (e: unknown) {\n  258 |       const msg = e instanceof Error ? e.message : \"Sign in failed.\";\n  259 |       setAuthError(msg);\n  260 |       throw e;\n  261 |     } finally {\n  262 |       setIsLoggingIn(false);\n  263 |     }\n  264 |   }, []);\n  265 | \n  266 |   const signOut = useCallback(async () => {\n  267 |     try {\n  268 |       await post(\"\/auth\/logout.php\");\n  269 |     } catch {\n  270 |       \/\/ Ignore logout errors\n  271 |     }\n  272 |     clearAuthToken();\n  273 |     localStorage.removeItem(\"app_current_user_email\");\n  274 |     setCurrentDoctor(null);\n  275 |     setAuthError(null);\n  276 |   }, []);\n  277 | \n  278 |   const updateProfile = useCallback(\n  279 |     async (_data: Partial<DoctorAccount>) => {\n  280 |       \/\/ Profile update handled by PHP backend\n  281 |       \/\/ API endpoint: POST \/api\/auth\/update_profile.php\n  282 |       \/\/ For now, no-op until endpoint is verified\n  283 |     },\n  284 |     [],\n  285 |   );\n  286 | \n  287 |   const getPendingAccounts = useCallback(async (): Promise<DoctorAccount[]> => {\n  288 |     try {\n  289 |       const result = await get<{ users: DoctorAccount[] }>(\"\/auth\/pending.php\");\n  290 |       return result.users ?? [];\n  291 |     } catch {\n  292 |       return [];\n  293 |     }\n  294 |   }, []);\n  295 | \n  296 |   const approveAccount = useCallback(async (id: number, role?: string) => {\n  297 |     await post(\"\/auth\/approve.php\", {\n  298 |       user_id: id,\n  299 |       ...(role ? { role } : {}),\n  300 |     });\n  301 |   }, []);\n  302 | \n  303 |   const approveAccountWithRole = useCallback(async (id: number, role: StaffRole) => {\n  304 |     await approveAccount(id, role);\n  305 |   }, [approveAccount]);\n  306 | \n  307 |   const rejectAccount = useCallback(async (id: number) => {\n  308 |     await post(\"\/auth\/reject.php\", { user_id: id });\n  309 |   }, []);\n  310 | \n  311 |   const reassignRole = useCallback(async (id: number, role: StaffRole) => {\n  312 |     await post(\"\/auth\/reassign_role.php\", {\n  313 |       user_id: id,\n  314 |       role,\n  315 |     });\n  316 |   }, []);\n  317 | \n  318 |   \/\/ \u2500\u2500 Patient auth \u2500\u2500\u2500\u2500\u25