        phone,\n  363 |         password,\n  364 |       });\n  365 |       localStorage.setItem(\"phpPatientToken\", result.token);\n  366 |       setCurrentPatient(result.patient);\n  367 |     } catch (e: unknown) {\n  368 |       const msg = e instanceof Error ? e.message : \"Sign in failed.\";\n  369 |       setAuthError(msg);\n  370 |       throw e;\n  371 |     } finally {\n  372 |       setIsLoggingIn(false);\n  373 |     }\n  374 |   }, []);\n  375 | \n  376 |   const patientSignOut = useCallback(() => {\n  377 |     localStorage.removeItem(\"phpPatientToken\");\n  378 |     setCurrentPatient(null);\n  379 |     setAuthError(null);\n  380 |   }, []);\n  381 | \n  382 |   const getPendingPatients = useCallback(async (): Promise<PatientAccount[]> => {\n  383 |     try {\n  384 |       const result = await get<{ patients: PatientAccount[] }>(\"\/auth\/patients\/pending.php\");\n  385 |       return result.patients ?? [];\n  386 |     } catch {\n  387 |       return [];\n  388 |     }\n  389 |   }, []);\n  390 | \n  391 |   const approvePatient = useCallback(async (id: number) => {\n  392 |     await post(\"\/auth\/patients\/approve.php\", {\n  393 |       patient_login_id: id,\n  394 |     });\n  395 |   }, []);\n  396 | \n  397 |   const rejectPatient = useCallback(async (id: number) => {\n  398 |     await post(\"\/auth\/patients\/reject.php\", {\n  399 |       patient_login_id: id,\n  400 |     });\n  401 |   }, []);\n  402 | \n  403 |   const updatePatientCredentials = useCallback(\n  404 |     async (_registerNumber: string, _newPhone?: string, _newPassword?: string) => {\n  405 |       \/\/ Patient credential update handled by PHP backend\n  406 |       \/\/ For now, no-op\n  407 |     },\n  408 |     [],\n  409 |   );\n  410 | \n  411 |   return (\n  412 |     <EmailAuthContext.Provider\n  413 |       value={{\n  414 |         currentDoctor,\n  415 |         currentPatient,\n  416 |         isInitializing,\n  417 |         isLoggingIn,\n  418 |         authError,\n  419 |         signUp,\n  420 |         signIn,\n  421 |         signOut,\n  422 |         updateProfile,\n  423 |         getPendingAccounts,\n  424 |         approveAccount,\n  425 |         approveAccountWithRole,\n  426 |         rejectAccount,\n  427 |         reassignRole,\n  428 |         patientSignUp,\n  429 |         patientSignIn,\n  430 |         patientSignOut,\n  431 |         getPendingPatients,\n  432 |         approvePatient,\n  433 |         rejectPatient,\n  434 |         updatePatientCredentials,\n  435 |       }}\n  436 |     >\n  437 |       {children}\n  438 |     <\/EmailAuthContext.Provider>\n  439 |   );\n  440 | }\n  441 | \n  442 | export function useEmailAuth(): EmailAuthContextValue {\n  443 |   const ctx = useContext(EmailAuthContext);\n  444 |   if (!ctx)\n  445 |     throw new Error(\"useEmailAuth must be used inside EmailAuthProvider\");\n  446 |   return ctx;\n  447 | }\n  448 | \n  449 | \/\/ \u2500\u2500 Inactivity Timer \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  450 | \n  451 | const INACTIVITY_TIMEOUT_MS = 15 * 60 * 1000; \/\/ 15 minutes\n  452 | const INACTIVITY_WARNING_MS = 13 * 60 * 1000; \/\/ 13 minutes (2 min before logout)\n  453 | const ACTIVITY_EVENTS = [\n  454 |   \"mousemove\",\n  455 |   \"keydown\",\n  456 |   \"click\",\n  457 |   \"touchstart\",\n  458 |   \"scroll\",\n  459 | ] as const;\n  460 | \n  461 | export interface InactivityTimerState {\n  462 |   showWarning: boolean;\n  463 |   secondsRemaining: number;\n  464 |   resetTimer: () => void;\n  465 | }\n  466 | \n  467 | export function useInactivityTimer(onLogout: () => void): InactivityTimerState {\n  468 |   const [showWarning, setShowWarning] = useState(false);\n  469 |   const [secondsRemaining, setSecondsRemaining] = useState(120);\n  470 | \n  471 |   const logoutTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);\n  472 |   const warningTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);\n  473 |   const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);\n  474 |   const lastActivityRef = useRef<number>(Date.now());\n  475 | \n  476 |   const clearAllTimers = useCallback(() => {\n  477 |     if (logoutTimerRef.current) clearTimeout(logoutTimerRef.current);\n  478 |     if (warningTimerRef.current) clearTimeout(warningTimerRef.current);\n  479 |     if (countdownRef.current) clearInterval(countdownRef.current);\n  480 |     logoutTimerRef.current = null;\n  481 |     warningTimerRef.current = null;\n  482 |     countdownRef.current = null;\n  483 |   }, []);\n  484 | \n  485 |   const startTimers = useCallback(() => {\n  486 |     clearAllTimers();\n  487 |     setShowWarning(false);\n  488 |     setSecondsRemaining(120);\n  489 | \n  490 |     warningTimerRef.current = setTimeout(() => {\n  491 |       setShowWarning(true);\n  492 |       setSecondsRemaining(120);\n  493 |       countdownRef.current = setInterval(() => {\n  494 |         setSecondsRemaining((s) => {\n  495 |           if (s <= 1) {\n  496 |             if (countdownRef.current) clearInterval(countdownRef.current);\n  497 |             return 0;\n  498 |           }\n  499 |           return s - 1;\n  500 |         });\n  501 |       }, 1000);\n  502 |     }, INACTIVITY_WARNING_MS);\n  503 | \n  504 |     logoutTimerRef.current = setTimeout(() => {\n  505 |       clearAllTimers();\n  506 |       setShowWarning(false);\n  507 |       onLogout();\n  508 |     }, INACTIVITY_TIMEOUT_MS);\n  509 |   }, [clearAllTimers, onLogout]);\n  510 | \n  511 |   const resetTimer = useCallback(() => {\n  512 |     lastActivityRef.current = Date.now();\n  513 |     startTimers();\n  514 |   }, [startTimers]);\n  515 | \n  516 |   useEffect(() => {\n  517 |     startTimers();\n  518 |     return clearAllTimers;\n  519 |   }, [startTimers, clearAllTimers]);\n  520 | \n  521 |   useEffect(() => {\n  522 |     const handler = () => resetTimer();\n  523 |     for (const ev of ACTIVITY_EVENTS) {\n  524 |       window.addEventListener(ev, handler, { passive: true });\n  525 |     }\n  526 |     return () => {\n  527 |       for (const ev of ACTIVITY_EVENTS) {\n  528 |         window.removeEventListener(ev, handler);\n  529 |       }\n  530 |     };\n  531 |   }, [resetTimer]);\n  532 | \n  533 |   return { showWarning, secondsRemaining, resetTimer };\n  534 | }\n  535 |",
